# Сборка документа «Смарт-контракты StepPay. Описание программы» по ЕСПД (ГОСТ 19.402-78 и смежные).
import sys
from gostdoc import Doc, build, AL

ORG = "Проект StepPay"
SYS = "Платформа StepPay. Смарт-контракты StepEscrow и StepAnchor"
