AUTHOR = "Гудков Павел Алексеевич\npavlusha220@yandex.ru\n+7 995 540-71-20"
DESIG = "STEPPAY.00001-01 13 01"


def make(pages):
    D = Doc()
    D.total = pages.get("__total__", "[N]")
    D.approval_and_title(ORG, SYS, KIND, DESIG, "Автор проекта", "2026", "", AUTHOR)
    entries = [
        (1, "1 ОБЩИЕ СВЕДЕНИЯ"), (2, "1.1 Обозначение и наименование программы"), (2, "1.2 Программное обеспечение, необходимое для функционирования"), (2, "1.3 Языки программирования"), (2, "1.4 Нормативные ссылки"), (2, "1.5 Термины и сокращения"),
        (1, "2 ФУНКЦИОНАЛЬНОЕ НАЗНАЧЕНИЕ"), (2, "2.1 Классы решаемых задач"), (2, "2.2 Сведения о функциональных ограничениях"),
        (1, "3 ОПИСАНИЕ ЛОГИЧЕСКОЙ СТРУКТУРЫ"), (2, "3.1 Состав и структура"), (2, "3.2 Данные и хранение"), (2, "3.3 Жизненный цикл сделки и этапа"), (2, "3.4 Режимы сделок"), (2, "3.5 Подписи, резерв и начало работы"), (2, "3.6 Приемка, голосование и споры"), (2, "3.7 Сроки и аварийный выход"), (2, "3.8 Расчет выплат, комиссия и возвраты"), (2, "3.9 Отказ токена: долг и вывод"), (2, "3.10 Хеш условий и соответствие ядру сделок"), (2, "3.11 Контракт StepAnchor"), (2, "3.12 Инварианты"), (2, "3.13 Перенос сделок приложения на контракт в тестовой сети"),
        (1, "4 ИСПОЛЬЗУЕМЫЕ ТЕХНИЧЕСКИЕ СРЕДСТВА"),
        (1, "5 ВЫЗОВ И ЗАГРУЗКА"),
        (1, "6 ВХОДНЫЕ ДАННЫЕ"),
        (1, "7 ВЫХОДНЫЕ ДАННЫЕ"),
        (1, "8 ПРОГРАММА И МЕТОДИКА ИСПЫТАНИЙ"), (2, "8.1 Объект и цель испытаний"), (2, "8.2 Виды и средства испытаний"), (2, "8.3 Результаты"),
        (1, "9 БЕЗОПАСНОСТЬ, ДОПУЩЕНИЯ И ИЗВЕСТНЫЕ ОГРАНИЧЕНИЯ"),
        (1, "ПРИЛОЖЕНИЕ А Перечень функций контракта StepEscrow"), (1, "ПРИЛОЖЕНИЕ Б Перечень событий, ошибок и параметров"), (1, "ПРИЛОЖЕНИЕ В Допустимые переходы состояний"), (1, "ПРИЛОЖЕНИЕ Г Соответствие правил ядра сделок и контракта"),
    ]
    D.toc(entries, pages)

    # ───────── 1 ─────────
    D.h1("1", "Общие сведения")
    D.h2("1.1", "Обозначение и наименование программы")
    D.p("Наименование: смарт-контракты платформы StepPay (далее контракты): StepEscrow (эскроу по этапам) и StepAnchor (публичный реестр корней якорей истории). Обозначение документа: " + DESIG + ". Тестовый токен TestRub входит в состав комплекта только для испытаний и в описание функционального назначения не включается.")
    D.p("Платформа StepPay реализует оплату по шагам в цифровых рублях: деньги резервируются и передаются исполнителю только за принятые этапы работы. Контракты являются эталонной реализацией правил на исполняемой среде EVM: те же правила реализованы в ядре сделок платформы (пакет engine), и обе реализации сверяются общими сценариями и случайными прогонами.")
    D.h2("1.2", "Программное обеспечение, необходимое для функционирования")
    D.p("Для работы контрактов необходима сеть, совместимая с виртуальной машиной Ethereum (EVM), и токен стандарта ERC-20 по интерфейсу transfer, transferFrom и balanceOf. Целевая версия набора инструкций: cancun. Для сборки, испытаний и развертывания используются:")
    D.bullet("компилятор Solidity версии 0.8.28 (в проекте подключается пакетом solcjs, загрузка двоичного компилятора не требуется);")
    D.bullet("среда разработки Hardhat 2, библиотека ethers версии 6;")
    D.bullet("среда выполнения Node.js (версия 20 и выше) и менеджер пакетов pnpm;")
    D.bullet("библиотека fast-check для случайных испытаний свойств.")
    D.p("Сторонние библиотеки контрактов (в том числе OpenZeppelin) не используются: интерфейс ERC-20 и защита от повторного входа написаны в самих контрактах.")
    D.h2("1.3", "Языки программирования")
    D.p("Контракты написаны на языке Solidity 0.8.28. Испытания, сценарии и скрипты развертывания написаны на JavaScript (Node.js), ядро сделок, с которым сверяются контракты, на TypeScript.")
    D.h2("1.4", "Нормативные ссылки")
    D.p("Документ оформлен с учетом требований Единой системы программной документации: ГОСТ 19.101-77 (виды программных документов), ГОСТ 19.103-77 (обозначение программ и программных документов), ГОСТ 19.104-78 (основные надписи), ГОСТ 19.105-78 (общие требования к программным документам), ГОСТ 19.106-78 (требования к программным документам, выполненным печатным способом), ГОСТ 19.402-78 (описание программы), ГОСТ 19.301-79 (программа и методика испытаний). Структура разделов 1-7 соответствует ГОСТ 19.402-78, раздел 8 построен по ГОСТ 19.301-79 в сокращенной форме.")
    D.h2("1.5", "Термины и сокращения")
    D.table("Термины и сокращения", ["Термин", "Определение"], [
        ["Сделка", "Договоренность об оплате работы по этапам, хранящаяся в контракте под номером dealId"],
        ["Этап", "Часть работы с фиксированной суммой, принимаемая и оплачиваемая отдельно"],
        ["Резерв", "Токены, внесенные в контракт и доступные только для выплаты по этапам или возврата"],
        ["Исполнитель", "Сторона, выполняющая работу и получающая оплату (автор проекта в краудфандинге, получатель гранта)"],
        ["Заказчик", "Сторона, вносящая всю сумму и принимающая этапы (в гранте: грантодатель)"],
        ["Спонсор", "Участник краудфандинга, вносящий часть суммы и голосующий за приемку этапов"],
        ["Приемщик", "Независимая сторона, решающая спор между заказчиком и исполнителем"],
        ["Запасной приемщик", "Второй независимый приемщик, который может решить спор со второй половины срока на спор, если основной молчит"],
        ["Хеш условий (contractHash)", "SHA-256 канонической записи условий сделки, хранимый в контракте для сверки с условиями вне цепочки"],
        ["Якорь", "Корень SHA-256 снимка истории платформы, публикуемый в контракте StepAnchor"],
        ["EVM", "Виртуальная машина Ethereum"],
        ["ERC-20", "Стандарт интерфейса взаимозаменяемого токена"],
        ["Базисный пункт (bps)", "Одна десятитысячная доля; 100 bps равны одному проценту"],
    ], [5.0, 11.4], 12)

    # ───────── 2 ─────────
    D.h1("2", "Функциональное назначение", newpage=True)
    D.h2("2.1", "Классы решаемых задач")
    D.p("Контракт StepEscrow решает следующие задачи:")
    D.bullet("прием и хранение резервов в токене сделки и учет вкладов каждого участника;")
    D.bullet("фиксация подписей сторон и начало работы только после полного резерва и всех подписей;")
    D.bullet("последовательное ведение этапов: сдача, приемка, отказ, спор, голосование спонсоров;")
    D.bullet("выплата исполнителю за принятые этапы и возврат остатка резерва во всех случаях закрытия сделки;")
    D.bullet("пропорциональное деление выплат и возвратов между спонсорами без потери копеек;")
    D.bullet("удержание комиссии платформы (до 10 процентов от суммы этапа);")
    D.bullet("автоматическую приемку при отсутствии ответа и аварийный выход по срокам, если сторона пропала;")
    D.bullet("защиту получателей друг от друга: отказ токена одному адресу не блокирует остальных.")
    D.p("Контракт StepAnchor решает задачу публичной и неизменяемой фиксации корней якорей истории платформы, чтобы переписать историю задним числом без обнаружения было нельзя.")
    D.h2("2.2", "Сведения о функциональных ограничениях")
    D.bullet("Контракт работает с одним токеном, заданным при развертывании. Токены с комиссией при переводе отклоняются, токены с ребейзом и хуками не поддерживаются.")
    D.bullet("Контракт не хранит условия сделки (названия этапов, описание, фото), а только суммы этапов, участников, сроки и хеш условий. Сами условия хранятся вне цепочки.")
    D.bullet("Подписи сторон в контракте это вызов функции sign с адреса стороны; юридически значимой квалифицированной электронной подписью по 63-ФЗ они не являются.")
    D.bullet("Предельные значения: не более 32 этапов в сделке, не более 64 вкладчиков в сделке, комиссия не более 1000 bps.")
    D.bullet("Контракт неизменяем: нет владельца, прокси, паузы и обновления. Исправление ошибок требует развертывания нового контракта.")
    D.bullet("Независимый аудит контрактов на момент составления документа не проводился.")

    # ───────── 3 ─────────
    D.h1("3", "Описание логической структуры", newpage=True)
    D.h2("3.1", "Состав и структура")
    D.table("Состав комплекта контрактов", ["Файл", "Назначение", "Строк"], [
        ["contracts/StepEscrow.sol", "Эскроу по этапам: три режима, подписи, резерв, голосование, споры, сроки, запасной приемщик, долги и вывод", "около 570"],
        ["contracts/StepAnchor.sol", "Публичная запись корней якорей истории платформы по порядку номеров", "35"],
        ["contracts/TestRub.sol", "Тестовый токен для испытаний (черный список и комиссия имитируются); в эксплуатацию не входит", "около 60"],
        ["rails/evm-rail.js", "Адаптер: контракт как денежный рельс с тем же интерфейсом, что и эмулятор на ядре сделок", ""],
        ["rails/anchor-chain.js, scripts/anchor.js", "Публикация корней якорей в сеть и сверка с сетью", ""],
        ["scripts/testnet-deal.js", "Прогон сделки в локальной или публичной сети с отчетом о транзакциях", ""],
        ["test/*.test.js", "Модульные, сценарные, инвариантные и дифференциальные испытания", ""],
    ], [5.2, 9.6, 1.6], 12)
    D.p("Контракт StepEscrow не наследует других контрактов. Единственная внешняя зависимость это токен ERC-20, адрес которого задается в конструкторе вместе с адресом получателя комиссии. Оба адреса неизменяемы. Конструктор отклоняет нулевые адреса и адрес токена, по которому нет кода контракта.")
    D.h2("3.2", "Данные и хранение")
    D.p("Состояние хранится в контракте. Основные структуры данных:")
    D.table("Структуры данных StepEscrow", ["Структура", "Поля", "Назначение"], [
        ["Stage", "amount (uint128), status, submittedAt, evidence (bytes32), activeSince, disputedAt", "Один этап: сумма, статус, моменты сдачи, начала работы и начала спора, хеш материалов сдачи"],
        ["Deadlines", "fundingSecs, stageSecs, disputeSecs (uint64)", "Сроки аварийного выхода в секундах, ноль означает без срока"],
        ["Params", "mode, executor, owner, arbiter, autoAcceptSecs, feeBps, contractHash, deadlines, backupArbiter", "Параметры создания сделки (служебная, передается в _create)"],
        ["Deal", "mode, status, executor, owner, arbiter, backupArbiter, executorSigned, ownerSigned, feeBps, autoAcceptSecs, createdAt, deadlines, contractHash, target, totalReserved, totalContributed, funders[], stages[]", "Сделка целиком"],
    ], [2.6, 8.0, 5.8], 11)
    D.p("Глобальное состояние контракта: dealCount (число сделок), totalLocked (сумма резервов всех сделок), totalOwed (сумма долгов получателям), отображения reserves[dealId][адрес] (текущий резерв участника), contributed[dealId][адрес] (всего внесено участником, вес голоса), votes[dealId][этап][адрес] (голос), owed[адрес] (долг). Веса голосов за и против по этапу накапливаются во внутренних отображениях.")
    D.h2("3.3", "Жизненный цикл сделки и этапа")
    D.p("Статусы сделки: Funding (сбор и подписи), Active (работа идет), Completed (все этапы приняты), Cancelled (закрыта с возвратом остатка). Статусы этапа: Pending (ждет очереди), Active (в работе), Submitted (сдан), Accepted (принят), Disputed (в споре), Failed (провален). В любой момент в работе, на сдаче или в споре находится не более одного этапа, этапы закрываются строго по порядку. Допустимые переходы приведены в приложении В.")
    D.p("Работа начинается автоматически, когда выполнены три условия: резерв равен целевой сумме, сделку подписали все стороны, статус равен Funding. В этот момент первый этап становится Active и запоминается момент начала работы над ним.")
    D.h2("3.4", "Режимы сделок")
    D.table("Режимы сделок", ["Режим", "Вносит деньги", "Принимает этап", "Подписывают", "Приемщик", "При отказе"], [
        ["Own (своя сделка)", "заказчик, всю сумму сразу", "заказчик", "исполнитель и заказчик", "обязателен", "спор: этап замораживается до решения приемщика"],
        ["Crowdfunding", "любые адреса, кроме автора, до цели", "спонсоры голосованием, вес равен внесенной сумме", "автор", "нет", "половина веса и больше против: этап провален, остаток возвращается"],
        ["Grant (грант)", "грантодатель, всю сумму сразу", "грантодатель", "получатель и грантодатель", "нет", "этап провален, остаток возвращается грантодателю"],
    ], [2.3, 2.6, 2.6, 2.9, 2.0, 4.0], 10)
    D.p("Автоприемка (любой адрес после autoAcceptSecs без ответа) действует в режимах Own и Crowdfunding и не действует в гранте.")
    D.h2("3.5", "Подписи, резерв и начало работы")
    D.p("Функция sign записывает подпись вызывающего адреса, если он исполнитель или (кроме краудфандинга) заказчик, и только пока сделка в статусе Funding. Повторная подпись отклоняется. Функция fund вносит токены: в режимах Own и Grant вносит только заказчик и ровно целевую сумму, в Crowdfunding любой адрес, кроме автора, не более недостающей суммы. Токены списываются через transferFrom, поэтому вкладчик предварительно разрешает контракту списание (approve). После списания контракт сверяет прирост своего баланса с суммой: если пришло не ровно столько (токен с комиссией, ребейз), операция откатывается.")
    D.h2("3.6", "Приемка, голосование и споры")
    D.bullet("submitStage: исполнитель сдает активный этап и прикладывает хеш материалов (описание и фото хранятся вне цепочки).")
    D.bullet("approveStage: заказчик (Own) или грантодатель (Grant) принимает сданный этап, выплата проводится сразу.")
    D.bullet("rejectStage: отказ с непустой причиной. В режиме Own этап переходит в спор, в гранте этап проваливается и остаток возвращается.")
    D.bullet("vote: спонсор голосует за или против, вес равен его вкладу, голос можно менять, пока этап не закрыт. Больше половины суммарного веса за принимает этап, половина и больше против проваливает.")
    D.bullet("openDispute: заказчик или исполнитель открывают спор по сданному этапу (режим Own).")
    D.bullet("resolveDispute: основной приемщик решает в любое время, запасной только со второй половины срока на спор (не раньше disputedAt плюс половина disputeSecs). Решение pay выплачивает исполнителю, иначе остаток возвращается.")
    D.bullet("autoAccept: любой адрес принимает сданный этап, если ответа нет дольше autoAcceptSecs.")
    D.bullet("cancel: заказчик (Own, Grant) или автор (Crowdfunding) закрывает сделку и возвращает остаток, если нет сданного или спорного этапа.")
    D.h2("3.7", "Сроки и аварийный выход")
    D.p("Три необязательных срока задаются при создании сделки (createDealEx, createDealFull) и после их истечения любой адрес может вызвать возврат без согласия сторон:")
    D.table("Сроки аварийного выхода", ["Функция", "Условие", "Результат"], [
        ["expireFunding", "сделка в статусе Funding, срок fundingSecs от создания истек", "сделка отменена, все резервы возвращены"],
        ["expireStage", "этап Active, срок stageSecs от начала работы над этапом истек", "этап провален, остаток возвращен"],
        ["expireDispute", "этап Disputed, срок disputeSecs от открытия спора истек", "этап провален, остаток возвращен заказчику"],
    ], [3.4, 7.2, 5.8], 11)
    D.p("Срок спора допустим только в режиме Own. Если срок равен нулю, соответствующий выход недоступен. Время берется из block.timestamp, сроки измеряются сутками, поэтому погрешность в секунды не влияет на результат.")
    D.h2("3.8", "Расчет выплат, комиссия и возвраты")
    D.p("Сумма этапа списывается с резервов вкладчиков пропорционально их текущим резервам методом наибольших остатков: каждому достается целая часть доли, а недостающие копейки по одной отдаются тем, у кого остаток от деления больше. Сумма частей всегда равна сумме этапа, отклонение от точной доли не больше одной копейки. Исполнитель получает сумму этапа за вычетом комиссии (amount умножить на feeBps и разделить на 10000, округление вниз), комиссия переводится получателю комиссии. При закрытии сделки с провалом или отменой остаток резерва возвращается вкладчикам в тех же долях, в каких он у них остался.")
    D.h2("3.9", "Отказ токена: долг и вывод")
    D.p("Выплата и возврат выполняются циклом по вкладчикам. Чтобы один получатель, которому токен отказал в приеме (черный список, запрет получения), не блокировал остальных, внутренний перевод _push при неудаче не откатывает операцию, а записывает сумму получателю в долг: owed[адрес] и totalOwed увеличиваются, выпускается событие Owed. Получатель забирает долг сам функцией claim(to), при необходимости на другой адрес. Если перевод при claim неудачен, операция откатывается и долг сохраняется. Токены долга остаются на балансе контракта, поэтому инвариант баланса имеет вид: баланс токенов контракта равен totalLocked плюс totalOwed.")
    D.h2("3.10", "Хеш условий и соответствие ядру сделок")
    D.p("При создании сделки передается contractHash: SHA-256 канонической записи условий (ключи по алфавиту, без пробелов), которую строит ядро сделок. Контракт хранит хеш и выводит его в событии DealCreated, поэтому условия вне цепочки можно сверить с цепочкой пересчетом хеша. Контракт хеш не проверяет и не интерпретирует. Правила, перечисленные в приложении Г, реализованы и в ядре сделок, и в контракте, а их эквивалентность проверяется испытаниями (раздел 8).")
    D.h2("3.11", "Контракт StepAnchor")
    D.p("Контракт принимает от издателя (адрес задается в конструкторе и неизменяем) корень якоря функцией anchor(n, root). Номера идут строго подряд, начиная с единицы, нулевой корень запрещен, перезапись записанного корня невозможна. Для каждого номера хранятся корень (roots) и время записи (anchoredAt), выпускается событие Anchored. Контракт ничего не знает о сделках и деньгах. Корень якоря вычисляется платформой как SHA-256 канонической записи снимка: длина журнала и хеш последней записи для каждой сделки, длина и хеш журнала операций с деньгами, корень предыдущего якоря.")
    D.h2("3.12", "Инварианты")
    D.p("Следующие свойства проверяются после каждого действия в случайных прогонах:")
    for t in ["баланс токенов контракта равен totalLocked плюс totalOwed;", "totalLocked равен сумме резервов по всем сделкам, а резервы каждой сделки совпадают с totalReserved внутри нее;", "завершенная или отмененная сделка не держит резервов;", "в активной сделке резерв равен сумме непринятых этапов;", "в сделке на этапе сбора резерв не превышает цель;", "токены не создаются и не пропадают: сумма балансов участников и контракта постоянна;", "этапы идут по порядку: принятые, не больше одного в работе, остальные ждут."]:
        D.bullet(t)

    D.h2("3.13", "Перенос сделок приложения на контракт в тестовой сети")
    D.p("Серверная часть приложения содержит зеркало: компонент, который после каждого действия по сделке воспроизводит его на контракте StepEscrow. Источником истины остается ядро сделок, зеркало читает журнал сделки и по порядку отправляет в сеть соответствующие вызовы: sign, fund, submitStage, approveStage, rejectStage, openDispute, vote, resolveDispute, autoAccept, expireFunding, expireStage, expireDispute, cancel. Зеркало включается переменными окружения (адрес узла, адреса контрактов, ключ счета платформы). Если они не заданы или заданы неверно, приложение работает как прежде.")
    D.p("У каждого участника есть собственный счет в сети. Закрытый ключ счета выводится функцией HKDF из секрета платформы и идентификатора участника, поэтому в базе данных ключи не хранятся. Газ оплачивает счет платформы. Токен tRUB тестовый: его выпуск открыт, ценности он не имеет и цифровым рублем не является. При включенном зеркале пополнение кошелька приложения сначала выпускает токены на счет участника, затем зачисляет сумму в ядре, а баланс «Свободно» сверяется с балансом токенов на счете.")
    D.p("Действия, привязанные ко времени (автоприемка, выход по сроку), повторяются каждые 30 секунд до 20 раз, пока контракт не примет вызов. Сбой сети помечает сделку как не перенесенную и не останавливает приложение. Запрос GET /deals/:id/chain/verify сравнивает статусы этапов и резервы в приложении и на контракте и сообщает расхождения. Ограничение: транзакции от имени участника отправляет платформа, а не сам участник со своего кошелька; в производственной версии подпись должна выполняться ключом участника.")
    # ───────── 4-7 ─────────
    D.h1("4", "Используемые технические средства", newpage=True)
    D.p("Контракты исполняются в любой сети, совместимой с EVM и поддерживающей набор инструкций cancun, на узлах этой сети. Для разработки и испытаний требуется компьютер с процессором архитектуры x86-64 или ARM64, не менее 4 ГБ оперативной памяти, Node.js версии 20 и выше, доступ к хранилищу пакетов (для первичной установки зависимостей). Для работы в публичной тестовой сети необходим адрес удаленного вызова процедур (RPC) узла сети, счет с тестовыми монетами для оплаты газа и закрытый ключ этого счета, который передается только через переменные окружения.")
    D.h1("5", "Вызов и загрузка")
    D.p("Развертывание выполняется скриптом scripts/testnet-deal.js (сделка целиком) и scripts/anchor.js (контракт StepAnchor и публикация якорей). Порядок развертывания StepEscrow:")
    D.bullet("развернуть токен ERC-20 сделок (для испытаний TestRub);")
    D.bullet("развернуть StepEscrow с параметрами (адрес токена, адрес получателя комиссии);")
    D.bullet("для каждой сделки вызвать createDeal, createDealEx или createDealFull с условиями; участники разрешают контракту списание токена (approve) и вызывают sign и fund;")
    D.bullet("дальнейшие вызовы: submitStage, approveStage, rejectStage, vote, openDispute, resolveDispute, autoAccept, cancel, expireFunding, expireStage, expireDispute, claim.")
    D.p("Параметры публичной сети задаются переменными окружения: SEPOLIA_RPC_URL или BASE_SEPOLIA_RPC_URL, DEPLOYER_PRIVATE_KEY (только тестовый ключ), EXPLORER_URL. Закрытые ключи в репозитории и журналах не хранятся. Команды: pnpm chain:local (локально), pnpm chain:sepolia (публичная тестовая сеть), pnpm anchor:publish (публикация якорей).")
    D.h1("6", "Входные данные")
    D.table("Входные данные создания сделки", ["Параметр", "Тип", "Описание и ограничения"], [
        ["mode", "Mode", "Own (0), Crowdfunding (1), Grant (2)"],
        ["executor", "address", "Исполнитель, не нулевой адрес"],
        ["owner", "address", "Заказчик или грантодатель; для Crowdfunding нулевой адрес; не равен исполнителю"],
        ["arbiter", "address", "Приемщик: обязателен в Own, нулевой в остальных режимах; не совпадает со сторонами"],
        ["stageAmounts", "uint128[]", "Суммы этапов в наименьших единицах токена, от 1 до 32 элементов, каждая больше нуля"],
        ["autoAcceptSecs", "uint64", "Срок автоприемки в секундах; для режимов Own и Crowdfunding больше нуля, для Grant любое"],
        ["feeBps", "uint16", "Комиссия в базисных пунктах, не более 1000"],
        ["contractHash", "bytes32", "SHA-256 условий сделки"],
        ["deadlines", "Deadlines", "Сроки в секундах (createDealEx, createDealFull); срок спора только для Own"],
        ["backupArbiter", "address", "Запасной приемщик (createDealFull): только Own, нужен срок на спор, не совпадает с исполнителем, заказчиком и основным приемщиком"],
    ], [3.3, 2.7, 10.4], 11)
    D.p("Прочие входные данные: dealId и номер этапа (нумерация с нуля), хеш материалов сдачи (evidence), хеш причины отказа или спора (reason, не нулевой), сумма взноса, голос, решение приемщика. Для StepAnchor: номер якоря и его корень.")
    D.h1("7", "Выходные данные")
    D.p("Результатом работы контрактов являются изменения состояния, перевод токенов и события журнала транзакций. Перечень событий приведен в приложении Б. Для чтения состояния предусмотрены функции: getDeal (режим, статус, участники, хеш условий, цель, резерв, число этапов), getStage (сумма, статус, момент сдачи, хеш материалов), getStageTimes, getDeadlines, backupArbiterOf, fundersOf, reservedSum, isSigned, а также открытые поля token, feeRecipient, dealCount, totalLocked, totalOwed, reserves, contributed, votes, owed. Контракт StepAnchor отдает count, roots, anchoredAt и publisher.")

    # ───────── 8 ─────────
    D.h1("8", "Программа и методика испытаний", newpage=True)
    D.h2("8.1", "Объект и цель испытаний")
    D.p("Объект испытаний: контракты StepEscrow и StepAnchor (раздел 3). Цель: подтвердить, что контракты реализуют правила раздела 3, сохраняют инварианты раздела 3.12 при любых последовательностях вызовов, дают те же результаты, что эталонное ядро сделок, и не допускают потери и создания средств.")
    D.h2("8.2", "Виды и средства испытаний")
    D.table("Виды испытаний", ["Вид", "Содержание", "Команда запуска"], [
        ["Модульные", "Права вызова, переходы статусов, подписи, голосование, споры, сроки, запасной приемщик, долг и вывод, комиссия, предельное число вкладчиков, отказ токена и токен с комиссией", "pnpm --filter @steppay/contracts test"],
        ["Сценарные (рельсы)", "Одни и те же 16 сценариев исполняются на ядре сделок и на контракте, результаты (принятые и отклоненные шаги, балансы, статусы) сравниваются до копейки", "входит в test"],
        ["Инвариантные", "Случайные последовательности действий в трех режимах, проверка инвариантов раздела 3.12 после каждого действия", "pnpm --filter @steppay/contracts test:invariants"],
        ["Дифференциальные", "Случайные сценарии (режимы, неровные взносы, комиссия, споры, автоприемка, сроки, запасной приемщик, шум из неверных вызовов) на ядре и контракте, расхождения недопустимы", "FC_DIFF_RUNS=500 pnpm --filter @steppay/contracts test:differential"],
        ["Свойства ядра", "400 хаотичных и 80 направляемых случайных прогонов ядра сделок, свыше двадцати условий после каждого шага", "pnpm --filter @steppay/engine test:properties"],
        ["Проверка испытаний мутациями", "В контракт вносятся осознанные поломки (сдвиг границ сроков и половины срока на спор), испытания обязаны упасть", "ручной прогон дифференциальных испытаний"],
        ["Газ", "Измерение стоимости приемки этапа и возврата при предельных 64 вкладчиках", "входит в test"],
    ], [3.4, 8.2, 4.8], 10)
    D.h2("8.3", "Результаты")
    D.p("На момент составления документа: контракты StepEscrow и StepAnchor проходят 48 испытаний пакета контрактов, 72 испытания ядра сделок, дифференциальные прогоны на 200 сценариях без расхождений, инвариантные прогоны без нарушений. Поломка границ сроков и половины срока на спор в контракте обнаруживается дифференциальными прогонами (поломка половины срока обнаруживается на 700 сценариях, на меньшем числе не гарантируется). При 64 вкладчиках приемка этапа с выплатой стоит около 1,27 млн единиц газа, провал этапа с возвратом всем около 1,22 млн единиц газа, что существенно ниже лимита блока. Испытания выполнены в локальной сети Hardhat. Контракты развернуты в публичной тестовой сети Sepolia, перенос сделок приложения проверен автоматическими тестами с подделкой сети и отдельными тестами на локальной сети; ручная проверка в Sepolia продолжается, ее результаты в состав данного документа не включены.")

    # ───────── 9 ─────────
    D.h1("9", "Безопасность, допущения и известные ограничения")
    D.p("Допущения, на которые опирается контракт, и меры защиты:")
    D.table("Допущения и меры защиты", ["Вопрос", "Решение"], [
        ["Повторный вход", "Функции с вызовами токена защищены собственным запретом повторного входа (nonReentrant); функции без внешних вызовов (sign, submitStage, openDispute) без защиты"],
        ["Тип токена", "Один токен на контракт, задается при развертывании; токены с комиссией при переводе отклоняются сверкой прироста баланса; ребейз и хуки не поддерживаются"],
        ["Блокировка выплат токеном", "Отказ токена одному получателю превращается в долг с выводом через claim, остальные получают деньги"],
        ["Администрирование", "Привилегированных адресов нет, кроме неизменяемого получателя комиссии и издателя StepAnchor; пауза и обновление отсутствуют"],
        ["Время", "block.timestamp; сроки сутки и больше"],
        ["Переполнение", "Solidity 0.8 с проверкой арифметики; суммы этапов хранятся в uint128, суммы по сделке в uint256"],
        ["Спам созданием сделок", "Создание доступно любому адресу, но средства не двигаются и вкладчики добровольно вносят деньги"],
        ["Подкуп приемщика", "Не технический риск; снижается реестром приемщиков платформы, репутацией и запасным приемщиком, но не исключается"],
    ], [4.2, 12.2], 11)
    D.p("Известные ограничения и непроверенное: независимый аудит не проводился (подготовлено задание для аудитора), формальной верификации нет, запуск в публичной сети не выполнялся, поведение с реальным токеном цифрового рубля зависит от его интерфейса и должно быть проверено отдельно. Допущения и открытые вопросы для аудитора приведены в документе docs/audit-brief.md репозитория проекта.")

